#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. See the STAGES section for usage.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

# The wizard library below is shared verbatim across wizards. SC1087: its `$e[Enter keeps
# current]` is literal prompt text after a colour variable, not an array expansion. SC2329:
# set_secret/set_var are library helpers this wizard does not need (nothing is pushed to CI).
# shellcheck disable=SC1087,SC2329
set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
#
# One-time human setup for agent-driven E2E against Vercel preview deployments.
# Writes the `.env.agent` contract read by tools/agent-inbox; see
# `.env.agent.example` for where each key comes from.
#
#   scripts/setup-agent-e2e.sh           # walk through every gate
#   scripts/setup-agent-e2e.sh --check   # read-only: verify and list missing gates
#
# This script never creates Resend keys and never changes Vercel or Supabase
# settings. It tells the human to do that and then verifies the result.
# ──────────────────────────────────────────────────────────────────────────

# Only the hosted *preview* Supabase project may be used. Never prod.
PREVIEW_PROJECT_REF="psbteexygkspyotkyflc"
PROD_PROJECT_REF="ejogxwyxmjbnnlvxzmji"
EXPECTED_SMTP_HOST="smtp.resend.com"

GATE_TITLES=(
  "H1 Resend receiving address (AGENT_INBOX_DOMAIN)"
  "H2 Resend inbox reader key (RESEND_INBOX_API_KEY)"
  "H3 Preview invite code (INVITE_CODE)"
  "H4 Vercel automation bypass (VERCEL_AUTOMATION_BYPASS_SECRET)"
  "H5 Preview Supabase (SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY)"
  "H6 Supabase preview SMTP is Resend (read-only)"
)
GATE_RESULTS=() # parallel to GATE_TITLES: "ok" or a short reason

# mask VALUE hides all but the last 4 characters, like scripts/bootstrap/main.py:_mask.
mask() {
  local value="$1" mask_chars=4
  if [[ -z "$value" || ${#value} -le $mask_chars ]]; then
    printf '****'
    return
  fi
  printf '%*s%s' $((${#value} - mask_chars)) '' "${value: -$mask_chars}" | tr ' ' '*'
}

# repo_root / main_checkout_root locate gitignored files that live in the
# primary checkout when this script runs from a linked git worktree.
main_checkout_root() {
  local common
  common=$(git rev-parse --path-format=absolute --git-common-dir 2>/dev/null) || return 1
  dirname "$common"
}

# dotenv_get FILE KEY prints KEY's value from a dotenv file without sourcing it.
dotenv_get() {
  local file="$1" key="$2" line value
  [[ -f "$file" ]] || return 1
  line=$(grep -E "^${key}=" "$file" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' || "$value" == \"*\" ]]; then value="${value:1:${#value}-2}"; fi
  [[ -n "$value" ]] || return 1
  printf '%s' "$value"
}

# bootstrap_get KEY reads from .env.bootstrap in this checkout, else the primary checkout.
bootstrap_get() {
  local key="$1" candidate root
  for candidate in "${BOOTSTRAP_ENV_FILE:-}" ".env.bootstrap"; do
    [[ -n "$candidate" ]] && dotenv_get "$candidate" "$key" && return 0
  done
  root=$(main_checkout_root) || return 1
  dotenv_get "$root/.env.bootstrap" "$key"
}

# agent_get KEY reads a captured value from .env.agent.
agent_get() { _existing "$1" || true; }

# http_status [curl args...] prints only the HTTP status code (000 on transport failure).
# Secrets go through `curl -K -` on stdin, never argv, so they stay out of `ps`.
http_status() {
  curl -sS -o /dev/null -w '%{http_code}' --max-time 20 "$@" 2>/dev/null || printf '000'
}

# json_field PATH reads stdin JSON and prints a dotted field ("" when absent).
json_field() {
  python3 -I -c '
import json, sys
try:
    node = json.load(sys.stdin)
    for part in sys.argv[1].split("."):
        node = node[int(part)] if isinstance(node, list) else node[part]
    print("" if node is None else node)
except Exception:
    pass
' "$1"
}

vercel_project_dir() {
  if [[ -f .vercel/project.json ]]; then printf '.'; return; fi
  local root
  root=$(main_checkout_root) || return 1
  [[ -f "$root/.vercel/project.json" ]] && printf '%s' "$root"
}

# latest_preview_url prints https://<host> of the newest READY preview deployment (newest first).
# AGENT_E2E_PREVIEW_URL overrides discovery (useful when `vercel` isn't logged in).
latest_preview_url() {
  if [[ -n "${AGENT_E2E_PREVIEW_URL:-}" ]]; then printf '%s' "${AGENT_E2E_PREVIEW_URL%/}"; return 0; fi
  command -v vercel >/dev/null 2>&1 || return 1
  local dir json host
  dir=$(vercel_project_dir) || return 1
  json=$(vercel ls --cwd "$dir" --environment preview --status READY \
    --format json --non-interactive 2>/dev/null) || return 1
  # The CLI has emitted both a bare array and {"deployments": [...]}; accept either.
  host=$(printf '%s' "$json" | json_field "deployments.0.url")
  [[ -n "$host" ]] || host=$(printf '%s' "$json" | json_field "0.url")
  [[ -n "$host" ]] || return 1
  [[ "$host" == http* ]] || host="https://$host"
  printf '%s' "$host"
}

pass() { printf '  %s✓ pass%s  %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ FAIL%s  %s\n' "$YELLOW" "$RESET" "$1"; }

# record_gate INDEX RESULT stores one gate's outcome for the closing summary.
record_gate() { GATE_RESULTS[$1]="$2"; }

# ── Verifications: each prints pass/fail, records the gate, and never prints secrets ──

verify_h1() {
  local domain; domain=$(agent_get AGENT_INBOX_DOMAIN)
  if [[ -z "$domain" ]]; then
    fail "AGENT_INBOX_DOMAIN is not set"; record_gate 0 "AGENT_INBOX_DOMAIN not set"; return 1
  fi
  if [[ ! "$domain" =~ ^[a-z0-9-]+\.resend\.app$ ]]; then
    fail "AGENT_INBOX_DOMAIN=$domain is not a <id>.resend.app address"
    record_gate 0 "AGENT_INBOX_DOMAIN is not a <id>.resend.app address"; return 1
  fi
  pass "AGENT_INBOX_DOMAIN=$domain"; record_gate 0 ok
}

verify_h2() {
  local key status
  key=$(agent_get RESEND_INBOX_API_KEY)
  if [[ -z "$key" ]]; then
    fail "RESEND_INBOX_API_KEY is not set"; record_gate 1 "RESEND_INBOX_API_KEY not set"; return 1
  fi
  status=$(printf 'header = "Authorization: Bearer %s"\n' "$key" |
    http_status -K - "https://api.resend.com/emails/receiving?limit=1")
  if [[ "$status" == "200" ]]; then
    pass "Resend GET /emails/receiving → 200 (key $(mask "$key"))"; record_gate 1 ok
  else
    fail "Resend GET /emails/receiving → $status (key $(mask "$key")); expects a valid full-access key (sending-only keys are rejected)"
    record_gate 1 "Resend receiving API returned $status"; return 1
  fi
}

verify_h3() {
  local code; code=$(agent_get INVITE_CODE)
  if [[ -z "$code" ]]; then
    fail "INVITE_CODE is not set"; record_gate 2 "INVITE_CODE not set"; return 1
  fi
  pass "INVITE_CODE is set ($(mask "$code"))"; record_gate 2 ok
}

verify_h4() {
  local secret url with_status bare_status
  secret=$(agent_get VERCEL_AUTOMATION_BYPASS_SECRET)
  if [[ -z "$secret" ]]; then
    fail "VERCEL_AUTOMATION_BYPASS_SECRET is not set"
    record_gate 3 "VERCEL_AUTOMATION_BYPASS_SECRET not set"; return 1
  fi
  if ! url=$(latest_preview_url); then
    fail "could not resolve the latest preview URL (run \`vercel login\`, or set AGENT_E2E_PREVIEW_URL)"
    record_gate 3 "could not resolve a preview URL to test the bypass against"; return 1
  fi
  with_status=$(printf 'header = "x-vercel-protection-bypass: %s"\n' "$secret" |
    http_status -K - "$url/login")
  bare_status=$(http_status "$url/login")
  if [[ ! "$with_status" =~ ^[23][0-9][0-9]$ ]]; then
    fail "$url/login with bypass header → $with_status (secret $(mask "$secret"))"
    record_gate 3 "bypass header rejected ($with_status) at $url"; return 1
  fi
  pass "$url/login with bypass header → $with_status (secret $(mask "$secret"))"
  if [[ "$bare_status" != "401" && "$bare_status" != "403" ]]; then
    note "  without the header it also returned $bare_status, so protection may be off and the secret is unproven"
  fi
  record_gate 3 ok
}

verify_h5() {
  local url key status
  url=$(agent_get SUPABASE_URL); key=$(agent_get SUPABASE_SERVICE_ROLE_KEY)
  if [[ -z "$url" || -z "$key" ]]; then
    fail "SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not both set"
    record_gate 4 "SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not both set"; return 1
  fi
  if [[ "$url" == *"$PROD_PROJECT_REF"* ]]; then
    fail "SUPABASE_URL points at PRODUCTION; refusing. Use the preview project."
    record_gate 4 "SUPABASE_URL is the production project"; return 1
  fi
  if [[ "$url" != "https://$PREVIEW_PROJECT_REF.supabase.co" ]]; then
    fail "SUPABASE_URL=$url is not https://$PREVIEW_PROJECT_REF.supabase.co"
    record_gate 4 "SUPABASE_URL is not the preview project"; return 1
  fi
  # Read-only: list one auth user to prove the service-role key is valid.
  status=$(printf 'header = "apikey: %s"\nheader = "Authorization: Bearer %s"\n' "$key" "$key" |
    http_status -K - "$url/auth/v1/admin/users?per_page=1")
  if [[ "$status" == "200" ]]; then
    pass "Supabase preview admin API → 200 (service role $(mask "$key"))"; record_gate 4 ok
  else
    fail "Supabase preview admin API → $status (service role $(mask "$key"))"
    record_gate 4 "service-role key rejected by preview Supabase ($status)"; return 1
  fi
}

verify_h6() {
  local token raw status body host
  if ! token=$(bootstrap_get SUPABASE_ACCESS_TOKEN); then
    fail "SUPABASE_ACCESS_TOKEN not found in .env.bootstrap"
    record_gate 5 "SUPABASE_ACCESS_TOKEN missing from .env.bootstrap"; return 1
  fi
  raw=$(printf 'header = "Authorization: Bearer %s"\n' "$token" |
    curl -sS --max-time 20 -K - -w '\n%{http_code}' \
      "https://api.supabase.com/v1/projects/$PREVIEW_PROJECT_REF/config/auth" 2>/dev/null) || raw=$'\n000'
  status="${raw##*$'\n'}"; body="${raw%$'\n'*}"
  host=$(printf '%s' "$body" | json_field "smtp_host")
  if [[ "$host" == "$EXPECTED_SMTP_HOST" ]]; then
    pass "preview auth smtp_host=$host (token $(mask "$token"))"; record_gate 5 ok
  elif [[ "$status" != "200" ]]; then
    fail "Supabase Management API → $status (token $(mask "$token")); refresh SUPABASE_ACCESS_TOKEN in .env.bootstrap"
    record_gate 5 "Supabase Management API returned $status (check SUPABASE_ACCESS_TOKEN)"; return 1
  else
    fail "preview auth smtp_host='${host:-<empty>}', expected $EXPECTED_SMTP_HOST"
    record_gate 5 "smtp_host is '${host:-<empty>}', not $EXPECTED_SMTP_HOST"; return 1
  fi
}

# run_checks runs every verification and prints the gate summary. Returns 1 if any gate is missing.
run_checks() {
  local i missing=0
  for i in 0 1 2 3 4 5; do GATE_RESULTS[i]="not checked"; done
  verify_h1 || true; verify_h2 || true; verify_h3 || true
  verify_h4 || true; verify_h5 || true; verify_h6 || true
  printf '\n  %sGate summary%s\n' "$BOLD" "$RESET"
  for i in "${!GATE_TITLES[@]}"; do
    if [[ "${GATE_RESULTS[i]}" == "ok" ]]; then
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "${GATE_TITLES[i]}"
    else
      printf '  %s✗%s %s%s: %s%s\n' "$YELLOW" "$RESET" "${GATE_TITLES[i]}" "$DIM" "${GATE_RESULTS[i]}" "$RESET"
      missing=$((missing + 1))
    fi
  done
  printf '\n'
  if (( missing )); then
    warn "$missing gate(s) missing. Run scripts/setup-agent-e2e.sh (without --check) to fix them."
    return 1
  fi
  say "All gates pass. Agents can use $ENV_FILE."
}

usage() {
  printf 'Usage: scripts/setup-agent-e2e.sh [--check]\n\n'
  printf '  (no args)  interactive one-time setup; writes %s\n' "$ENV_FILE"
  printf '  --check    read-only: verify every gate and list the missing ones (exit 1 if any)\n'
}

run_wizard() {

# .env.agent is the gitignored contract with tools/agent-inbox. Run from the repo root so the
# relative path (and `.vercel`) resolve no matter where the script is invoked from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE="${AGENT_ENV_FILE:-.env.agent}"

case "${1:-}" in
  --check)
    printf '\n%s%s  Agent preview-E2E: gate check%s\n\n' "$BOLD" "$BLUE" "$RESET"
    run_checks
    return $?
    ;;
  -h | --help)
    usage
    return 0
    ;;
  "") ;;
  *)
    usage >&2
    return 2
    ;;
esac

TOTAL_STAGES=6

# write_env keeps an existing file's mode, so a copied .env.agent.example could stay world-readable
# while it receives secrets. Create the file if needed and force owner-only access first.
[[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
chmod 600 "$ENV_FILE"

banner "Agent preview-E2E setup (.env.agent)"

# ── H1: Resend receiving address ──────────────────────────────────────────
stage "Resend: managed receiving address (H1)"
say "Agents read OTP emails from a catch-all <id>.resend.app address. No DNS is needed."
open_url "https://resend.com/emails/receiving"
step "Emails → Receiving → the ⋯ menu → Receiving address."
step "Enable the managed address if it is off, then copy it (looks like abc123.resend.app)."
ask AGENT_INBOX_DOMAIN "Paste the receiving domain:"
AGENT_INBOX_DOMAIN="${AGENT_INBOX_DOMAIN#*@}" # tolerate a pasted full address
write_env AGENT_INBOX_DOMAIN "$AGENT_INBOX_DOMAIN"
verify_h1 || true
pause "Press Enter for the next stage"

# ── H2: Resend inbox reader key ───────────────────────────────────────────
stage "Resend: inbox reader API key (H2)"
say "Sending-only keys cannot read received mail, so this needs its own full-access key."
open_url "https://resend.com/api-keys"
step "Create API key → name it agent-inbox-reader → permission: Full access."
step "Copy the key now; Resend only shows it once."
ask_secret RESEND_INBOX_API_KEY "Paste the key:"
write_env RESEND_INBOX_API_KEY "$RESEND_INBOX_API_KEY"
verify_h2 || true
pause "Press Enter for the next stage"

# ── H3: Preview invite code ───────────────────────────────────────────────
stage "Vercel: preview INVITE_CODE (H3)"
say "Sign-up is invite-gated. We try to read the preview value from Vercel first."
invite=""
if command -v vercel >/dev/null 2>&1 && pull_dir=$(vercel_project_dir); then
  pull_tmp=$(mktemp)
  # Sensitive vars pull back empty, which falls through to the manual prompt below.
  if vercel env pull "$pull_tmp" --cwd "$pull_dir" --environment=preview --yes >/dev/null 2>&1; then
    invite=$(dotenv_get "$pull_tmp" INVITE_CODE || true)
  fi
  rm -f "$pull_tmp"
fi
if [[ -n "$invite" ]]; then
  say "Read INVITE_CODE from Vercel preview env ($(mask "$invite"))."
else
  warn "Could not read INVITE_CODE from Vercel (sensitive, not logged in, or unset)."
  open_url "https://vercel.com/dashboard"
  step "Project → Settings → Environment Variables → INVITE_CODE (Preview)."
  step "If it is hidden, use whatever value you have stored for it."
  ask_secret INVITE_CODE "Paste the preview invite code:"
  invite="$INVITE_CODE"
fi
write_env INVITE_CODE "$invite"
verify_h3 || true
pause "Press Enter for the next stage"

# ── H4: Vercel automation bypass ──────────────────────────────────────────
stage "Vercel: Protection Bypass for Automation (H4)"
say "Lets agents reach protected preview URLs via the x-vercel-protection-bypass header."
open_url "https://vercel.com/dashboard"
step "Project → Settings → Deployment Protection → Protection Bypass for Automation."
step "Enable it if it is off (this wizard will not change Vercel settings for you)."
step "Copy the secret."
ask_secret VERCEL_AUTOMATION_BYPASS_SECRET "Paste the bypass secret:"
write_env VERCEL_AUTOMATION_BYPASS_SECRET "$VERCEL_AUTOMATION_BYPASS_SECRET"
verify_h4 || true
pause "Press Enter for the next stage"

# ── H5: Preview Supabase ──────────────────────────────────────────────────
stage "Supabase: preview project credentials (H5)"
say "Used to purge throwaway test users. Preview project only: ref $PREVIEW_PROJECT_REF."
default_url=$(bootstrap_get SUPABASE_URL_PREVIEW || true)
default_key=$(bootstrap_get SUPABASE_SERVICE_ROLE_KEY_PREVIEW || true)
if [[ -n "$default_url" && -n "$default_key" ]]; then
  say "Found SUPABASE_URL_PREVIEW and SUPABASE_SERVICE_ROLE_KEY_PREVIEW in .env.bootstrap ($(mask "$default_key"))."
  if confirm "Use them?"; then
    SUPABASE_URL="$default_url"; SUPABASE_SERVICE_ROLE_KEY="$default_key"
  fi
fi
if [[ -z "${SUPABASE_URL:-}" ]]; then
  open_url "https://supabase.com/dashboard/project/$PREVIEW_PROJECT_REF/settings/api-keys"
  step "Copy the Project URL (https://$PREVIEW_PROJECT_REF.supabase.co)."
  ask SUPABASE_URL "Paste the project URL:"
  step "Reveal and copy the service_role secret key."
  ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the service role key:"
fi
write_env SUPABASE_URL "$SUPABASE_URL"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
verify_h5 || true
pause "Press Enter for the final verification"

# ── Final: full read-only verification ────────────────────────────────────
stage "Verify everything"
say "Read-only checks against Resend, the latest preview deployment, and Supabase."
checks_ok=0
run_checks || checks_ok=1

if (( checks_ok )); then
  # Don't call finish: it would print "Setup complete" while a gate is still missing.
  (( ${#WRITTEN_ENV[@]} )) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  warn "Setup incomplete: fix the failing gates above, then re-run this script (or use --check)."
  return 1
fi

finish
}

run_wizard "$@"; exit
